INSERT INTO campaigns (title,description,host_organizer,campaign_url,image_url,start_date,end_date,region,category,status,submission_type) VALUES ('등촌1종합사회복지관 플로깅 ''줍줍이들’','양천구 등촌주공1단지아파트와 근린공원 일대 환경개선을 위한 평일/토요일 집단 플로깅 자원봉사 캠페인. 복지관에서 집게·봉투 받아 진행, 분리수거·활동일지·인증 후 봉사시간 1시간 인정, 5인 이상 단체신청 가능','등촌1종합사회복지관','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346882**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346882)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346882**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346882)','2025-10-01','2025-12-31','서울 양천구 등촌주공1단지아파트, 인근 근린공원','RECYCLING','ACTIVE','MANUAL_GUIDE'),('제주형 2인1조 장소무제한 플로깅(환경정화 자원봉사)','시민·청소년 누구나 2인 1조로 집·공원·거리 등 어디서나 ''타임스탬프'' 앱으로 인증사진(3장 이상)과 일지 작성·메일 제출하는 방식의 집단형 플로깅. 활동 전·중·후 시간 인증, 장소명 기재 필수. 1일 2시간, 허위등록 불인정','제주시청','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3357016**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3357016)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3357016**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3357016)','2025-10-01','2025-12-31','전국 및 제주도, 집 주변/공원 등 장소 제한 없음','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('음암거점 플로킹 캠페인 환경정화','충남 서산시 음암면주민자치센터 일대에서 성인·청소년·기업·단체가 함께 집결하여 3시간 이내 플로킹(조깅+쓰레기줍기) 환경정화 활동을 실시하는 집단 실천형 환경 캠페인. 주말(토) 40명 한정','음암면 거점캠프(충남 서산시), 충청남도 서산시','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358310**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358310)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358310**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358310)','2025-11-15','2025-11-15','충남 서산시 음암면 도당로 27-6(음암면주민자치센터)','CONSERVATION','EXPECT','MANUAL_GUIDE'),('나주시 공공장소 플로깅 – 바로온 봉사 어플 연계 환경정화','전라남도 나주시 공공장소(공원, 하천 등)에서 누구나 참여, 바로온봉사 App을 활용해 인증사진(얼굴+종량제봉투) 1시간 플로깅. QR코드/어플에서만 신청·실적 자동연계, 월 8회 제한, 종료 후 익월 실적반영, 아파트 단지 제외','전라남도 자원봉사센터','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358547**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358547)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358547**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358547)','2025-10-01','2025-12-31','전라남도 나주시 내 아파트 제외 모든 공공장소','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('무안군 공공장소 플로깅 – 바로온봉사 앱 연계 환경정화','전남 무안군 내 모든 공공장소에서 누구나 참여, 바로온봉사 App 필수. 20L 종량제봉투·집게·장갑(개인준비), 활동 셀프사진 필수, 1시간 이상, 월 8회까지 실적. 결과보고서 양식 메일 제출, 같은 장소 반복 및 학교·아파트 내 상시활동 불가','무안군자원봉사센터','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3363775','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3363775','2025-10-01','2025-12-31','전라남도 무안군 내 모든 공공장소(아파트·학교 내 제외)','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('전라남도 공공장소 플로깅 – 바로온봉사 앱 연계 환경정화','전라남도 도내 공공장소 어디든 20L 종량제봉투 지참, 바로온봉사 앱(GPS체크 포함) 인증으로 활동 실적 인정. 1일 1회 셀프사진(3회/GPS경로별)·장소중복 불가, 활동 규정 미달시 반영불가, 관할 센터 실적 승인','전라남도자원봉사센터','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358240','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358240','2025-10-01','2025-12-31','전라남도 전역 내 공공장소(공원, 하천, 거리 등, 아파트/교내 제외)','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('구미 행복홀씨입양사업 환경정화·EM비누 체험·지구시민교육','구미시립중앙도서관 농구장 앞 집결, 도서관주변·상가거리 환경정화, 쓰레기 줄이기 홍보, 지구시민교육과 EM 주물럭비누 만들기 결합형 캠페인. 3시간 봉사실적','지구시민운동연합경북지부','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3362799**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3362799)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3362799**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3362799)','2025-11-05','2025-11-05','경상북도 구미시 형곡동 구미시립중앙도서관 일대','RECYCLING','EXPECT','MANUAL_GUIDE'),('센터 내 시설정화 봉사','기관(센터) 내에서 실시하는 실내·실외 환경정화 봉사활동. 봉사신청 후 사정상 불참 시 반드시 사전 연락 필수, 주요 환경정화 및 위생관리 중심, 시설이용자 안전 위한 집단 캠페인','사단법인 진주사랑의집','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3336028','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3336028','2025-09-01','2025-11-24','센터 내','CONSERVATION','EXPECT','MANUAL_GUIDE'),('진해해양공원 맑은 바다 만들기 및 줍깅 캠페인','경남 진해해양공원에서 건강과 해양환경을 동시에 지키는 거리 줍깅 캠페인. 참가자 누구나 간편한 복장만 착용, 준비물 불필요, 현장 인증샷 촬영 및 사전 불참연락 강조. 시민참여 해양쓰레기 정화 캠페인','진해해양공원','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3334927','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3334927','2025-09-01','2025-11-30','경상남도 진해해양공원','CONSERVATION','EXPECT','MANUAL_GUIDE'),('부산현대미술관 산책 – 환경정화 및 SNS 챌린지','부산현대미술관 야외 일원에서 자율 환경정화(쓰레기 줍기), ‘워크온’ 앱으로 활동거리/걸음수/시간 인증, SNS 활동후기 게시 챌린지형. 1일 1시간, 월 최대 4회','부산현대미술관','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3334689','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3334689','2025-09-01','2025-11-30','부산광역시 부산현대미술관 야외 일원(자율)','CONSERVATION','ACTIVE','MANUAL_GUIDE');

